#include "fixed-position-house-solver.h"

std::optional<charm::v1n7::zebra_puzzle::HouseAssignment> charm::v1n7::zebra_puzzle::solve_house_assignment(std::size_t house_count,const std::vector<std::string>& items,const std::vector<charm::v1n7::zebra_puzzle::FixedHouseClue>& clues){if(house_count>10||items.size()!=house_count)return std::nullopt;std::set<std::string> domain;for(const auto& item:items)if(item.empty()||!domain.insert(item).second)return std::nullopt;std::vector<std::string> positions(house_count);std::set<std::string> fixed;for(const auto& clue:clues){if(clue.position>=house_count||domain.count(clue.item)==0||!fixed.insert(clue.item).second||!positions[clue.position].empty())return std::nullopt;positions[clue.position]=clue.item;}std::vector<std::string> remaining;for(const auto& item:domain)if(fixed.count(item)==0)remaining.push_back(item);auto it=remaining.begin();for(auto& position:positions)if(position.empty())position=*it++;return HouseAssignment{positions};}
